use vstd::prelude::*;

verus! {

fn transpose(arr: Vec<Vec<i8>>) -> (result: Vec<Vec<i8>>)
    requires
        // The matrix must be non‐empty…
        arr.len() > 0,
        // …and all rows must have the same length
        forall |i: usize| 0 <= i && i < arr.len() ==> arr[i].len() == arr[0].len(),
    ensures
        // The result has swapped dimensions…
        result.len() == arr[0].len(),
        // …and each row of the result has length equal to the number of input rows
        forall |j: usize| 0 <= j && j < arr[0].len() ==> result[j].len() == arr.len(),
        // And the usual transpose property:
        //   result[j][i] == arr[i][j]
        forall |i: usize, j: usize|
            0 <= i && i < arr.len() &&
            0 <= j && j < arr[0].len() ==>
                result[j][i] == arr[i][j],
{
    // Number of rows in the input
    let m = arr.len();
    // Number of columns in the input (we assume at least one row)
    let n = arr[0].len();

    // Prepare the output with n rows, each with capacity m
    let mut result: Vec<Vec<i8>> = (0..n).map(|_| Vec::with_capacity(m)).collect();

    // Fill the transposed matrix
    for row in arr {
        for (j, val) in row.into_iter().enumerate() {
            result[j].push(val);
        }
    }

    result
}

} // end verus!

